package io.github.chronicle.core.encounters;

import io.github.chronicle.core.history.ImmutableHistoryArchive;
import java.io.*;
import java.nio.*;
import java.nio.channels.FileChannel;
import java.nio.charset.*;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.*;

/** Bounded live at-most-once journal. Completed records leave live history only after exact archive publication. */
public final class EncounterOperationStore {
    public static final long MAX_FILE_BYTES = 512 * 1024; private static final int MAGIC=0x43484F45, SCHEMA=1;
    private final Path file; private final ImmutableHistoryArchive archive; private byte[] observed; private EncounterOperationJournal journal;
    public EncounterOperationStore(Path file, ImmutableHistoryArchive archive){if(file==null||file.getFileName()==null)throw new IllegalArgumentException("encounter operation file is required");this.file=file.toAbsolutePath().normalize();this.archive=Objects.requireNonNull(archive,"operation archive is required");}
    public synchronized EncounterOperationJournal load()throws IOException{if(!Files.exists(file)){observed=null;journal=EncounterOperationJournal.empty();return journal;}byte[] bytes=current();try{journal=decode(bytes);observed=bytes.clone();return journal;}catch(RuntimeException e){throw new IOException("encounter operation journal is invalid and was preserved: "+file,e);}}
    public synchronized EncounterOperationJournal state(){requireLoaded();return journal;}
    public synchronized Optional<EncounterOperation> liveOperation(UUID operationId){requireLoaded();Objects.requireNonNull(operationId,"operation UUID is required");return Optional.ofNullable(journal.operations().get(operationId));}
    /** Controlled recovery seam: only monotonic states of the exact current live plans are accepted. */
    public synchronized void save(EncounterOperationJournal replacement)throws IOException{requireLoaded();Objects.requireNonNull(replacement,"operation journal is required");if(!journal.operations().keySet().equals(replacement.operations().keySet()))throw new IllegalArgumentException("operation journal replacement cannot add or remove operation UUIDs");for(UUID id:journal.operations().keySet())validateTransition(journal.operations().get(id),replacement.operations().get(id));persist(replacement);}
    public synchronized EncounterOperation create(EncounterOperation operation)throws IOException{requireLoaded(); if(journal.operations().containsKey(operation.operationId()))throw new IllegalStateException("operation UUID is already live; never replan or reuse it"); if(archive.read(operation.operationId().toString()).isPresent())throw new IllegalStateException("operation UUID is archived; never replan or reuse it"); persist(journal.put(operation));return operation;}
    /** Call and await this durable transition before the runtime attempts an external entity spawn. */
    public synchronized EncounterOperation claim(UUID operationId,UUID entityId)throws IOException{return transition(operationId,operation->operation.claim(entityId));}
    public synchronized EncounterOperation markSpawned(UUID operationId,UUID entityId)throws IOException{return transition(operationId,operation->operation.markSpawned(entityId));}
    public synchronized EncounterOperation complete(UUID operationId)throws IOException{return transition(operationId,EncounterOperation::complete);}
    /** Recovery marks a held claimed plan uncertain; it never returns entries to PLANNED. */
    public synchronized EncounterOperation uncertain(UUID operationId)throws IOException{return transition(operationId,EncounterOperation::uncertain);}
    public synchronized EncounterOperation reviewUncertain(UUID operationId)throws IOException{return transition(operationId,EncounterOperation::reviewed);}
    public synchronized void archiveComplete(UUID operationId)throws IOException{requireLoaded();EncounterOperation operation=live(operationId);if(operation.terminal()!=EncounterOperation.Terminal.COMPLETE&&operation.terminal()!=EncounterOperation.Terminal.REVIEWED)throw new IllegalStateException("only complete or reviewed encounter operations may be archived");archive.publish(operationId.toString(),encodeOperation(operation));persist(journal.remove(operationId));}
    public synchronized Optional<EncounterOperation> archived(UUID operationId)throws IOException{Objects.requireNonNull(operationId,"operation UUID is required");return archive.read(operationId.toString()).map(EncounterOperationStore::decodeOperation);}
    /** Exact retry lookup: an existing live/archive identity must match the proposed immutable plan. */
    public synchronized EncounterOperation ensure(EncounterOperation proposed)throws IOException{requireLoaded();Objects.requireNonNull(proposed,"encounter operation is required");EncounterOperation live=journal.operations().get(proposed.operationId());if(live!=null){if(!sameIdentityAndPlan(live,proposed))throw new IllegalStateException("encounter operation UUID conflicts with an existing live plan");return live;}Optional<EncounterOperation> old=archived(proposed.operationId());if(old.isPresent()){if(!sameIdentityAndPlan(old.get(),proposed)||(old.get().terminal()!=EncounterOperation.Terminal.COMPLETE&&old.get().terminal()!=EncounterOperation.Terminal.REVIEWED))throw new IllegalStateException("encounter operation UUID conflicts with archived evidence");return old.get();}return create(proposed);}
    public synchronized int archiveAllComplete()throws IOException{requireLoaded();List<UUID> complete=journal.operations().values().stream().filter(operation->operation.terminal()==EncounterOperation.Terminal.COMPLETE||operation.terminal()==EncounterOperation.Terminal.REVIEWED).map(EncounterOperation::operationId).toList();for(UUID id:complete)archiveComplete(id);return complete.size();}
    private EncounterOperation transition(UUID id,java.util.function.UnaryOperator<EncounterOperation> transition)throws IOException{requireLoaded();EncounterOperation old=live(id),next=transition.apply(old);validateTransition(old,next);persist(journal.replace(next));return next;}
    private EncounterOperation live(UUID id){Objects.requireNonNull(id,"operation UUID is required");EncounterOperation operation=journal.operations().get(id);if(operation==null)throw new IllegalArgumentException("operation UUID is not live; archived/uncertain operations cannot auto-replay");return operation;}
    private void requireLoaded(){if(journal==null)throw new IllegalStateException("load a valid encounter operation journal before mutating it");}
    private static void validateTransition(EncounterOperation old,EncounterOperation next){if(!old.operationId().equals(next.operationId())||!old.actorId().equals(next.actorId())||!old.groupId().equals(next.groupId())||!old.groupFingerprint().equals(next.groupFingerprint())||!old.planHash().equals(next.planHash())||old.entries().size()!=next.entries().size())throw new IllegalArgumentException("operation identity and immutable plan cannot change");for(int i=0;i<old.entries().size();i++){EncounterSpawnEntry before=old.entries().get(i),after=next.entries().get(i);if(!samePlan(before,after))throw new IllegalArgumentException("operation spawn plan cannot change");if(before.stage()==EncounterSpawnEntry.Stage.PLANNED&&after.stage()==EncounterSpawnEntry.Stage.SPAWNED)throw new IllegalArgumentException("planned spawn entry must be durably claimed before spawned");if(after.stage().ordinal()<before.stage().ordinal())throw new IllegalArgumentException("operation spawn stage cannot rewind");}if(old.terminal()==next.terminal())return;if(old.terminal()==EncounterOperation.Terminal.OPEN&&(next.terminal()==EncounterOperation.Terminal.COMPLETE||next.terminal()==EncounterOperation.Terminal.UNCERTAIN))return;if(old.terminal()==EncounterOperation.Terminal.UNCERTAIN&&next.terminal()==EncounterOperation.Terminal.REVIEWED)return;throw new IllegalArgumentException("operation terminal state cannot rewind or bypass review");}
    private static boolean samePlan(EncounterSpawnEntry a,EncounterSpawnEntry b){return a.entityId().equals(b.entityId())&&a.entityType().equals(b.entityType())&&a.dimension().equals(b.dimension())&&Double.doubleToLongBits(a.x())==Double.doubleToLongBits(b.x())&&Double.doubleToLongBits(a.y())==Double.doubleToLongBits(b.y())&&Double.doubleToLongBits(a.z())==Double.doubleToLongBits(b.z());}
    private static boolean sameIdentityAndPlan(EncounterOperation a,EncounterOperation b){if(!a.operationId().equals(b.operationId())||!a.actorId().equals(b.actorId())||!a.groupId().equals(b.groupId())||!a.groupFingerprint().equals(b.groupFingerprint())||!a.planHash().equals(b.planHash())||a.entries().size()!=b.entries().size())return false;for(int i=0;i<a.entries().size();i++)if(!samePlan(a.entries().get(i),b.entries().get(i)))return false;return true;}
    private void persist(EncounterOperationJournal next)throws IOException{byte[] old=observed==null?null:current();if(observed==null&&Files.exists(file))throw new IOException("encounter operation journal appeared outside Chronicle; reload before saving");if(old!=null&&!MessageDigest.isEqual(old,observed))throw new IOException("encounter operation journal changed outside Chronicle; reload before saving");byte[] bytes=encode(next);if(bytes.length>MAX_FILE_BYTES)throw new IOException("encounter operation journal exceeds 512 KiB limit");writeAtomic(old,bytes);journal=next;observed=bytes;}
    private byte[] current()throws IOException{if(!Files.isRegularFile(file))throw new IOException("encounter operation journal is not a regular file");if(Files.size(file)>MAX_FILE_BYTES)throw new IOException("encounter operation journal exceeds 512 KiB limit");return Files.readAllBytes(file);}
    private void writeAtomic(byte[] old,byte[] bytes)throws IOException{Files.createDirectories(file.getParent());Path temp=Files.createTempFile(file.getParent(),file.getFileName().toString(),".tmp"),backupTemp=null;try{force(temp,bytes);if(old!=null){verify(old);Path backup=file.resolveSibling(file.getFileName()+".bak");backupTemp=Files.createTempFile(file.getParent(),backup.getFileName().toString(),".tmp");force(backupTemp,old);move(backupTemp,backup);backupTemp=null;verify(old);}move(temp,file);}finally{Files.deleteIfExists(temp);if(backupTemp!=null)Files.deleteIfExists(backupTemp);}}
    private void verify(byte[] expected)throws IOException{if(!MessageDigest.isEqual(expected,current()))throw new IOException("encounter operation journal changed outside Chronicle during save; reload before retrying");}
    static byte[] encode(EncounterOperationJournal journal){try{ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(DataOutputStream out=new DataOutputStream(bytes)){out.writeInt(MAGIC);out.writeInt(SCHEMA);out.writeLong(journal.revision());out.writeInt(journal.operations().size());for(EncounterOperation operation:journal.operations().values())writeOperation(out,operation);}return bytes.toByteArray();}catch(IOException impossible){throw new IllegalStateException(impossible);}}
    static EncounterOperationJournal decode(byte[] bytes){try(DataInputStream in=new DataInputStream(new ByteArrayInputStream(bytes))){if(in.readInt()!=MAGIC||in.readInt()!=SCHEMA)throw new IllegalArgumentException("operation journal magic/schema is invalid");long revision=in.readLong();int count=in.readInt();if(count<0||count>EncounterOperationJournal.MAX_LIVE_OPERATIONS)throw new IllegalArgumentException("operation count is invalid");Map<UUID,EncounterOperation> values=new LinkedHashMap<>();for(int i=0;i<count;i++){EncounterOperation operation=readOperation(in);if(values.putIfAbsent(operation.operationId(),operation)!=null)throw new IllegalArgumentException("duplicate operation UUID");}if(in.read()!=-1)throw new IllegalArgumentException("operation journal has trailing bytes");return new EncounterOperationJournal(revision,values);}catch(EOFException e){throw new IllegalArgumentException("operation journal is truncated",e);}catch(IOException e){throw new IllegalArgumentException("operation journal cannot be decoded",e);}}
    private static byte[] encodeOperation(EncounterOperation operation){try{ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(DataOutputStream out=new DataOutputStream(bytes)){writeOperation(out,operation);}return bytes.toByteArray();}catch(IOException impossible){throw new IllegalStateException(impossible);}}
    private static EncounterOperation decodeOperation(byte[] bytes){try(DataInputStream in=new DataInputStream(new ByteArrayInputStream(bytes))){EncounterOperation result=readOperation(in);if(in.read()!=-1)throw new IllegalArgumentException("archived operation has trailing bytes");return result;}catch(IOException e){throw new IllegalArgumentException("archived operation cannot be decoded",e);}}
    private static void writeOperation(DataOutputStream out,EncounterOperation o)throws IOException{text(out,o.operationId().toString(),36);text(out,o.actorId().toString(),36);text(out,o.groupId(),256);text(out,o.groupFingerprint(),64);text(out,o.planHash(),64);out.writeInt(o.entries().size());for(EncounterSpawnEntry e:o.entries()){text(out,e.entityId().toString(),36);text(out,e.entityType(),256);text(out,e.dimension(),256);out.writeDouble(e.x());out.writeDouble(e.y());out.writeDouble(e.z());text(out,e.stage().name(),16);}text(out,o.terminal().name(),16);}
    private static EncounterOperation readOperation(DataInputStream in)throws IOException{UUID operation=uuid(text(in,36,"operation UUID")),actor=uuid(text(in,36,"actor UUID"));String group=text(in,256,"group ID"),fingerprint=text(in,64,"group fingerprint"),plan=text(in,64,"plan hash");int count=in.readInt();if(count<1||count>64)throw new IllegalArgumentException("entry count is invalid");List<EncounterSpawnEntry> entries=new ArrayList<>();for(int i=0;i<count;i++)entries.add(new EncounterSpawnEntry(uuid(text(in,36,"entity UUID")),text(in,256,"entity type"),text(in,256,"dimension"),in.readDouble(),in.readDouble(),in.readDouble(),enumValue(EncounterSpawnEntry.Stage.class,text(in,16,"entry stage"))));return new EncounterOperation(operation,actor,group,fingerprint,plan,entries,enumValue(EncounterOperation.Terminal.class,text(in,16,"terminal")));}
    private static void text(DataOutputStream out,String value,int max)throws IOException{byte[] bytes=value.getBytes(StandardCharsets.UTF_8);if(bytes.length<1||bytes.length>max)throw new IllegalArgumentException("encoded text is outside limits");out.writeInt(bytes.length);out.write(bytes);} private static String text(DataInputStream in,int max,String label)throws IOException{int length=in.readInt();if(length<1||length>max)throw new IllegalArgumentException(label+" length is invalid");byte[] bytes=in.readNBytes(length);if(bytes.length!=length)throw new EOFException(label+" is truncated");try{return StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).onUnmappableCharacter(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(bytes)).toString();}catch(CharacterCodingException e){throw new IllegalArgumentException(label+" is not valid UTF-8",e);}} private static UUID uuid(String value){try{UUID id=UUID.fromString(value);if(!id.toString().equals(value))throw new IllegalArgumentException();return id;}catch(RuntimeException e){throw new IllegalArgumentException("UUID is not canonical",e);}} private static <T extends Enum<T>>T enumValue(Class<T>type,String value){try{return Enum.valueOf(type,value);}catch(RuntimeException e){throw new IllegalArgumentException("unknown "+type.getSimpleName(),e);}} private static void force(Path p,byte[] b)throws IOException{try(FileChannel c=FileChannel.open(p,StandardOpenOption.WRITE,StandardOpenOption.TRUNCATE_EXISTING)){ByteBuffer x=ByteBuffer.wrap(b);while(x.hasRemaining())c.write(x);c.force(true);}} private static void move(Path a,Path b)throws IOException{try{Files.move(a,b,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(AtomicMoveNotSupportedException e){throw new IOException("atomic replacement is not supported for encounter operation journal",e);}}
}
